public int maximalSquare(char[][] matrix) {
    int m = matrix.length, n = matrix[0].length;
    int best = 0;
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (matrix[r][c] != '1') {
                continue;
            }
            int side = 1;
            while (r + side < m && c + side < n && validBorder(matrix, r, c, side)) {
                side++;
            }
            best = Math.max(best, side);
        }
    }
    return best * best;
}

private boolean validBorder(char[][] matrix, int r, int c, int side) {
    for (int c2 = c; c2 <= c + side; c2++) {
        if (matrix[r + side][c2] != '1') {
            return false;
        }
    }
    for (int r2 = r; r2 <= r + side; r2++) {
        if (matrix[r2][c + side] != '1') {
            return false;
        }
    }
    return true;
}

